/**
 * A pinned Agent Substrate release bundle and its content check.
 *
 * A release module under `releases/` is generated by
 * `scripts/vendor-agent-substrate-release.ts` from the upstream commit the release tag names.
 * It records the git blob of every upstream file it was rendered from, the release's image
 * digests, the Kubernetes scope of every object, and the rendered objects. The composition
 * refuses a bundle whose canonical content hash differs from the reviewed value, so an edit to
 * the vendored objects, images or source identity is a reviewed change to that value too.
 */
import { createHash } from 'node:crypto';
import { TypeKroError } from '../../core/errors.js';

/** One Kubernetes object of the release bundle. */
export interface AgentSubstrateManifest {
  readonly apiVersion: string;
  readonly kind: string;
  readonly metadata: {
    readonly name: string;
    readonly namespace?: string;
  } & Readonly<Record<string, unknown>>;
  readonly [field: string]: unknown;
}

export interface AgentSubstrateReleaseDocument {
  /** The upstream file the object comes from, relative to the repository root. */
  readonly source: string;
  /**
   * The object's Kubernetes scope: from the bundle's own CRDs for `ate.dev` kinds, and from the
   * pinned Kubernetes OpenAPI paths for built-in kinds.
   */
  readonly scope: 'Cluster' | 'Namespaced';
  readonly manifest: AgentSubstrateManifest;
}

export interface AgentSubstrateRelease {
  /** The release tag, for example `v1.0.0`. */
  readonly version: string;
  /** The commit the tag names. */
  readonly sourceCommit: string;
  /** The Kubernetes version whose OpenAPI paths gave the scope of built-in kinds. */
  readonly kubernetesVersion: string;
  /** Every upstream file the bundle was rendered from, with its git blob at `sourceCommit`. */
  readonly sourceFiles: readonly { readonly path: string; readonly gitBlob: string }[];
  /**
   * The release images by name, as `ghcr.io/agent-substrate/substrate/<name>:<version>@sha256:…`.
   * Each digest is the image index the release tag names, and every platform image in it carries
   * `org.opencontainers.image.revision` equal to `sourceCommit`.
   */
  readonly images: Readonly<Record<string, string>>;
  readonly documents: readonly AgentSubstrateReleaseDocument[];
}

function canonical(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(canonical);
  if (value !== null && typeof value === 'object') {
    return Object.fromEntries(
      Object.keys(value)
        .sort()
        .map((key) => [key, canonical((value as Record<string, unknown>)[key])])
    );
  }
  return value;
}

/** sha256 of the release's canonical JSON (object keys sorted at every level). */
export function agentSubstrateReleaseSha256(release: AgentSubstrateRelease): string {
  return createHash('sha256')
    .update(JSON.stringify(canonical(release)))
    .digest('hex');
}

const releaseImage =
  /^ghcr\.io\/agent-substrate\/substrate\/[a-z0-9-]+:(v[^@]+)@sha256:[0-9a-f]{64}$/u;

interface PodSpecShape {
  readonly containers?: readonly { readonly image?: string }[];
  readonly initContainers?: readonly { readonly image?: string }[];
}

/** The images of every container and init container in a workload object. */
export function workloadImages(manifest: AgentSubstrateManifest): string[] {
  const pod = (manifest.spec as { template?: { spec?: PodSpecShape } } | undefined)?.template?.spec;
  return [...(pod?.containers ?? []), ...(pod?.initContainers ?? [])].map(
    (container) => container.image ?? ''
  );
}

/**
 * Throws unless `release` hashes to `expectedSha256` and every workload image is one of the
 * release's pinned images.
 */
export function verifyAgentSubstrateRelease(
  release: AgentSubstrateRelease,
  expectedSha256: string
): void {
  const actual = agentSubstrateReleaseSha256(release);
  if (actual !== expectedSha256) {
    throw new TypeKroError(
      `The Agent Substrate ${release.version} bundle does not match its reviewed content (sha256 ${actual}, expected ${expectedSha256}).`,
      'AGENT_SUBSTRATE_BUNDLE_MODIFIED',
      { version: release.version, actual, expected: expectedSha256 }
    );
  }
  const pinned = new Set(Object.values(release.images));
  for (const image of pinned) {
    if (releaseImage.exec(image)?.[1] !== release.version) {
      throw new TypeKroError(
        `Agent Substrate image ${image} is not a ${release.version} release image pinned by digest.`,
        'AGENT_SUBSTRATE_IMAGE_NOT_PINNED',
        { image }
      );
    }
  }
  for (const { manifest } of release.documents) {
    for (const image of workloadImages(manifest)) {
      if (!pinned.has(image)) {
        throw new TypeKroError(
          `${manifest.kind}/${manifest.metadata.name} runs ${image || 'no image'}, which is not a ${release.version} release image.`,
          'AGENT_SUBSTRATE_IMAGE_NOT_PINNED',
          { kind: manifest.kind, name: manifest.metadata.name, image }
        );
      }
    }
  }
}
